  "Type": "AWS::IAM::Role",
  "Properties": {
    "Description": "Rolle des Fristenweckers: Benachrichtigung senden und Ausfuehrungen protokollieren",
    "AssumeRolePolicyDocument": {
      "Version": "2012-10-17",
      "Statement": [
        {
          "Effect": "Allow",
          "Principal": {
            "Service": "states.amazonaws.com"
          },
          "Action": "sts:AssumeRole",
          "Condition": {
            "StringEquals": {
              "aws:SourceAccount": {
                "Ref": "AWS::AccountId"
              }
            }
          }
        }
      ]
    },
    "Policies": [
      {
        "PolicyName": "fristenwecker",
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Sid": "PublishFristTopic",
              "Effect": "Allow",
              "Action": "sns:Publish",
              "Resource": {
                "Ref": "FristTopic"
              }
            },
            {
              "Sid": "LogDeliveryRequiresWildcard",
              "Effect": "Allow",
              "Action": [
                "logs:CreateLogDelivery",
                "logs:GetLogDelivery",
                "logs:UpdateLogDelivery",
                "logs:DeleteLogDelivery",
                "logs:ListLogDeliveries",
                "logs:PutResourcePolicy",
                "logs:DescribeResourcePolicies",
                "logs:DescribeLogGroups"
              ],
              "Resource": "*"
            }
          ]
        }
      }
    ]
  }
},

